import type { buildBook } from "./book";

type Book = ReturnType<typeof buildBook>;
type Diff = { path: string; sent: unknown; got: unknown };
type Client = { call(tool: string, args: Record<string, unknown>): Promise<unknown> };

const TOLERANCE = 0.005;

function flatten(v: unknown, path: string, out: Map<string, unknown>): void {
  if (Array.isArray(v)) {
    if (v.length === 0) out.set(path, v);
    v.forEach((x, i) => flatten(x, `${path}[${i}]`, out));
  } else if (v !== null && typeof v === "object") {
    const keys = Object.keys(v);
    if (keys.length === 0) out.set(path, v);
    for (const k of keys) flatten((v as Record<string, unknown>)[k], path ? `${path}.${k}` : k, out);
  } else {
    out.set(path, v);
  }
}

function same(a: unknown, b: unknown): boolean {
  if (typeof a === "number" && typeof b === "number") return Math.abs(a - b) <= TOLERANCE;
  if (Array.isArray(a) && Array.isArray(b)) return a.length === 0 && b.length === 0;
  if (a !== null && b !== null && typeof a === "object" && typeof b === "object") {
    return Object.keys(a).length === 0 && Object.keys(b).length === 0;
  }
  return a === b;
}

export function diffBook(sent: Book, readback: Book): Diff[] {
  const s = new Map<string, unknown>();
  const g = new Map<string, unknown>();
  flatten(sent, "", s);
  flatten(readback ?? {}, "", g);
  const paths = [...s.keys(), ...[...g.keys()].filter((p) => !s.has(p))];
  const diffs: Diff[] = [];
  for (const path of paths) {
    const a = s.get(path);
    const b = g.get(path);
    if (!s.has(path) || !g.has(path) || !same(a, b)) diffs.push({ path, sent: a, got: b });
  }
  return diffs;
}

export async function writeBook(
  book: Book,
  client: Client,
  opts: { retries?: number } = {},
): Promise<{ ok: boolean; attempts: number; diffs: Diff[] }> {
  const maxAttempts = 1 + Math.max(0, opts.retries ?? 1);
  let diffs: Diff[] = [];
  let attempts = 0;
  while (attempts < maxAttempts) {
    attempts++;
    try {
      await client.call("edit_table_blocks", { book });
      const res = (await client.call("inspect_table_blocks", {})) as { book?: Book } | null | undefined;
      diffs = diffBook(book, (res?.book ?? {}) as Book);
      if (diffs.length === 0) return { ok: true, attempts, diffs };
    } catch (e) {
      diffs = [{ path: "$error", sent: undefined, got: e instanceof Error ? e.message : String(e) }];
    }
  }
  return { ok: false, attempts, diffs };
}
EOF
cat > tests/cfo-mcp.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { buildBook } from "../src/cfo/book";
import { diffBook, writeBook } from "../src/cfo/mcp";

const book = buildBook({
  periodDays: 30,
  promoted: "a",
  assumptions: { engineerMonthlyLoadedUsd: 15000, scaleSessionsPerWeek: 70 },
  setups: [{ id: "a", label: "A", costUsd: 30, sessions: 10, survivingChanges: 6, unattendedShare: 0.5 }],
});
const clone = () => JSON.parse(JSON.stringify(book));

function fake(readbacks: unknown[]) {
  const calls: string[] = [];
  let i = 0;
  return {
    calls,
    call: async (tool: string) => {
      calls.push(tool);
      if (tool === "inspect_table_blocks") return readbacks[Math.min(i++, readbacks.length - 1)];
      return {};
    },
  };
}

test("matching readback succeeds in one attempt", async () => {
  const c = fake([{ book: clone() }]);
  expect(await writeBook(book, c)).toEqual({ ok: true, attempts: 1, diffs: [] });
  expect(c.calls).toEqual(["edit_table_blocks", "inspect_table_blocks"]);
});

test("numbers within 0.005 match, beyond do not", () => {
  const b = clone();
  b.department[0].monthlySpendUsd += 0.004;
  expect(diffBook(book, b)).toEqual([]);
  b.department[0].monthlySpendUsd += 0.01;
  expect(diffBook(book, b)).toHaveLength(1);
});

test("diff reports path, sent and got", () => {
  const b = clone();
  b.department[0].label = "Z";
  expect(diffBook(book, b)).toEqual([{ path: "department[0].label", sent: "A", got: "Z" }]);
});

test("mismatch retries once then fails with diffs", async () => {
  const bad = clone();
  bad.department[0].label = "Z";
  const c = fake([{ book: bad }]);
  const r = await writeBook(book, c);
  expect(r.ok).toBe(false);
  expect(r.attempts).toBe(2);
  expect(r.diffs[0]!.path).toBe("department[0].label");
});

test("retry can recover", async () => {
  const bad = clone();
  bad.department[0].label = "Z";
  const r = await writeBook(book, fake([{ book: bad }, { book: clone() }]));
  expect(r).toEqual({ ok: true, attempts: 2, diffs: [] });
});

test("missing readback is empty, all fields differ", async () => {
  const r = await writeBook(book, fake([{}]), { retries: 0 });
  expect(r.ok).toBe(false);
  expect(r.attempts).toBe(1);
  expect(r.diffs.length).toBeGreaterThan(0);
});

test("client errors count as attempts and are not thrown", async () => {
  const client = { call: async () => { throw new Error("boom"); } };
  const r = await writeBook(book, client);
  expect(r.ok).toBe(false);
  expect(r.attempts).toBe(2);
  expect(r.diffs[0]!.got).toBe("boom");
});
EOF
